import math
from itertools import combinations

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def gcd_three(a, b, c):
    return gcd(a, gcd(b, c))

def is_good_set(a, b, c):
    # Assuming a < b < c based on how we iterate

    # Condition 1: GCD of all three is 1
    if gcd_three(a, b, c) != 1:
        return False

    # Condition 2: Divisibility checks
    # Pair {a, b} -> needs c | ab
    if (a * b) % c != 0:
        return False

    # Pair {a, c} -> needs b | ac
    if (a * c) % b != 0:
        return False

    # Pair {b, c} -> needs a | bc
    if (b * c) % a != 0:
        return False

    return True

def search_good_sets(max_c):
    good_numbers = set()

    # Iterate through all triples a < b < c up to max_c
    # We start from 1, but since we are looking for factors, we might only need to check a>=1.
    # Let's start from a=1, b=2, c=3.

    for a in range(1, max_c + 1):
        for b in range(a + 1, max_c + 1):
            for c in range(b + 1, max_c + 1):
                if is_good_set(a, b, c):
                    m = a * b * c
                    good_numbers.add(m)

    return sorted(list(good_numbers))

# Initial search limit based on "small prime factors" requirement.
# Let's test up to a moderate limit and see if we get enough candidates.
# If the 20th smallest is large, this needs adjustment, but we must start somewhere concrete.
MAX_C_LIMIT = 50 
candidates = search_good_sets(MAX_C_LIMIT)

print(f"Found {len(candidates)} good numbers up to c={MAX_C_LIMIT}.")
if len(candidates) >= 20:
    print("The first 20 smallest good numbers are:")
    print(candidates[:20])
else:
    print(f"Need to increase MAX_C_LIMIT. Found only {len(candidates)} candidates.")

