    while b:
        a, b = b, a % b
    return a

def gcd_three(a, b, c):
    return gcd(a, gcd(b, c))

def check_condition_1(U):
    # U = {a, b, c, d}
    # Check GCD of all 4 triples
    for combo in itertools.combinations(U, 3):
        a, b, c = combo
        if gcd_three(a, b, c) != 1:
            return False
    return True

def check_condition_2(U):
    # U = {a, b, c, d}
    elements = list(U)

    # Iterate over all 6 pairs of indices (i1, i2)
    for indices_pair in itertools.combinations(range(4), 2):
        i1, i2 = indices_pair
        x = elements[i1]
        y = elements[i2]

        # Check if there exists z in U \ {x, y} such that z | xy
        found_divisor = False
        # Iterate over all 4 possible indices k for z
