            # z must be an element different from x and y
            if k != i1 and k != i2:
                z = elements[k]
                if (x * y) % z == 0:
                    found_divisor = True
                    break

        if not found_divisor:
            return False
    return True

def find_good_sets_size_4(max_element=30):
